const crypto = require('crypto');

// HMAC-SHA256 over `${timestamp}\n${method}\n${path}\n${body}`, verified by
// convex/http.ts. The path is part of the MAC, so the signature is only valid
// for the endpoint it was made for. The HTTP node posts to the returned `url`,
// so the path signed and the path called can't drift apart.
function signForLendLoop(path, payload) {
  const secret = $env.N8N_TO_LENDLOOP_SECRET;
  const baseUrl = $env.CONVEX_SITE_URL;
  if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');
  if (!baseUrl) throw new Error('CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const mac = crypto.createHmac('sha256', secret).update([timestamp, 'POST', path, body].join('\n')).digest('hex');
  return { url: baseUrl.replace(/\/+$/, '') + path, body, timestamp, signature: `v2=${mac}` };
}

// Convex returns overdue loans a page at a time. The first run comes from a
// trigger; later runs come from "More pages?" carrying the previous page's
// asOf and nextCursor, so every page of one run uses the same date.
const MAX_PAGES = 50;
if ($runIndex >= MAX_PAGES) {
  throw new Error(`Overdue loans still had more pages after ${MAX_PAGES}; stopping instead of looping forever`);
}
const previous = $input.first().json;
const payload = previous.nextCursor ? { asOf: previous.asOf, cursor: previous.nextCursor } : {};
return [{ json: signForLendLoop('/n8n/overdue-loans', payload) }];

// One item per overdue loan on this page. Convex already excluded loans
// reminded today, and recorded loans with no verified email as failed
// reminders (they show on the admin page), so only the count arrives here.
const { loans = [], undeliverable = 0 } = $input.first().json;
if (undeliverable > 0) {
  console.log(`[lendloop] ${undeliverable} overdue loan(s) have no verified email; recorded as failed reminders`);
}
return loans.map((loan) => ({ json: loan }));

// MOCK CHANNEL (see "Send notification (mock)" in the loan events workflow).
// Each reminder is handled on its own: one failure is recorded as `failed`
// for that loan instead of aborting the whole batch.
return $input.all().map(({ json: loan }) => {
  const masked = loan.borrowerEmail.replace(/^(.).*(@.*)$/, '$1***$2');
  try {
    if ($env.SIMULATE_NOTIFY_FAILURE === 'true') throw new Error('Simulated notification channel outage');
    const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
    console.log(`[lendloop] reminder to ${masked}: Hi ${loan.borrowerName}, the ${loan.toolName} was due back ${days} ago.`);
    return { json: { loanId: loan.loanId, reminderKey: loan.reminderKey, status: 'sent', channel: 'mock' } };
  } catch (error) {
    return {
      json: {
        loanId: loan.loanId,
        reminderKey: loan.reminderKey,
        status: 'failed',
        channel: 'mock',
        detail: String(error.message).slice(0, 200),
      },
    };
  }
});

const crypto = require('crypto');

// HMAC-SHA256 over `${timestamp}\n${method}\n${path}\n${body}`, verified by
// convex/http.ts. The path is part of the MAC, so the signature is only valid
// for the endpoint it was made for. The HTTP node posts to the returned `url`,
// so the path signed and the path called can't drift apart.
function signForLendLoop(path, payload) {
  const secret = $env.N8N_TO_LENDLOOP_SECRET;
  const baseUrl = $env.CONVEX_SITE_URL;
  if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');
  if (!baseUrl) throw new Error('CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const mac = crypto.createHmac('sha256', secret).update([timestamp, 'POST', path, body].join('\n')).digest('hex');
  return { url: baseUrl.replace(/\/+$/, '') + path, body, timestamp, signature: `v2=${mac}` };
}

// reminderKey makes the write-back idempotent: retries can't duplicate it.
return $input.all().map(({ json: r }) => ({
  json: signForLendLoop('/n8n/reminders', {
    loanId: r.loanId,
    reminderKey: r.reminderKey,
    status: r.status,
    channel: r.channel,
    ...(r.detail ? { detail: r.detail } : {}),
  }),
}));
